<?php
require_once __DIR__ . '/includes/layout.php';require_auth();
$id=filter_input(INPUT_GET,'carrier_id',FILTER_VALIDATE_INT);if(!$id){flash('error','Invalid carrier.');redirect('carrier_list.php');}
$s=db()->prepare('SELECT name,email,phone_number,company FROM carriers WHERE carrier_id=?');$s->bind_param('i',$id);$s->execute();$carrier=$s->get_result()->fetch_assoc();if(!$carrier){flash('error','Carrier not found.');redirect('carrier_list.php');}
$s=db()->prepare('SELECT o.order_id,o.order_date,o.status,o.total_amount,c.name customer_name FROM orders o JOIN customers c ON c.customer_id=o.customer_id WHERE o.carrier_id=? ORDER BY o.order_date DESC');$s->bind_param('i',$id);$s->execute();$orders=$s->get_result();
page_start('Carrier orders','carriers');?>
<div class="page-heading"><div><h1><?= e($carrier['name']) ?></h1><p><?= e($carrier['company']) ?> · <?= e($carrier['email']) ?></p></div><a class="btn btn-secondary" href="manage_carriers.php">Back</a></div><section class="card"><?php if($orders->num_rows): ?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Status</th><th>Total</th></tr></thead><tbody><?php while($o=$orders->fetch_assoc()): ?><tr><td><a href="invoice.php?order_id=<?= (int)$o['order_id'] ?>">#<?= (int)$o['order_id'] ?></a></td><td><?= e($o['customer_name']) ?></td><td><?= e($o['order_date']) ?></td><td><span class="badge"><?= e($o['status']) ?></span></td><td>$<?= number_format((float)$o['total_amount'],2) ?></td></tr><?php endwhile; ?></tbody></table></div><?php else: ?><div class="empty">No orders assigned to this carrier.</div><?php endif; ?></section><?php page_end();?>
